package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import java.io.File;
import java.util.ArrayList;
import java.util.concurrent.Callable;
import java.util.concurrent.Executors;

import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbLiteral;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreValueCacheConcurrencyTest {

	@Test
	void concurrentReadersSeeCompleteCachedValues(@TempDir File directory) throws Exception {
		ValueStore store = new ValueStore(directory, new LmdbStoreConfig());
		try (var executor = Executors.newFixedThreadPool(4)) {
			var workers = new ArrayList<Callable<Void>>();
			for (int worker = 0; worker < 4; worker++) {
				workers.add(() -> {
					for (int iteration = 0; iteration < 250_000; iteration++) {
						long id = 100L + (iteration & 7) * 4L;
						String label = "cached-value-" + id;
						store.cacheValue(id, new LmdbLiteral(store.getRevision(), label,
								CoreDatatype.XSD.STRING, id));
						LmdbValue cached = store.cachedValue(id);
						if (cached != null) {
							assertNotNull(((LmdbLiteral) cached).getLabel());
							assertEquals(label, cached.stringValue());
							assertEquals(CoreDatatype.XSD.STRING, ((LmdbLiteral) cached).getCoreDatatype());
						}
					}
					return null;
				});
			}
			for (var result : executor.invokeAll(workers)) {
				result.get();
			}
		} finally {
			store.close();
		}
	}
}
